function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value is an integer between -10000 and 10000.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is between 1 and 100000.';
  return null;
}

