function maxResult(nums, k) {
  const n = nums.length;
  const best = new Array(n);
  best[0] = nums[0];
  const deque = [0];
  let head = 0;

  for (let i = 1; i < n; i++) {
    while (deque[head] < i - k) {
      head++;
    }
    best[i] = nums[i] + best[deque[head]];
    while (deque.length > head && best[deque[deque.length - 1]] <= best[i]) {
      deque.pop();
    }
    deque.push(i);
  }
  return best[n - 1];
}

