function maxResult(nums, k) {
  // Try every sequence of jumps from index 0 and keep the best total.
  const n = nums.length;
  let answer = -Infinity;
  const walk = (index, total) => {
    if (index === n - 1) { answer = Math.max(answer, total); return; }
    for (let step = 1; step <= k && index + step < n; step++) walk(index + step, total + nums[index + step]);
  };
  walk(0, nums[0]);
  return answer;
}

