function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const k = rand() < 0.5 ? int(1, 20) : int(1, 2500);
    return [Array.from({ length: n }, () => int(-10000, 10000)), k];
  }
  const n = int(1, 10);
  const k = int(1, n + 2);
  const span = rand() < 0.2 ? 10000 : 10;
  const bias = rand() < 0.3 ? -span : 0;
  return [Array.from({ length: n }, () => Math.max(-10000, Math.min(10000, int(-span, span) + bias))), k];
}
